<?php

namespace PhpOffice\PhpSpreadsheet\Calculation\LookupRef;

use PhpOffice\PhpSpreadsheet\Calculation\ArrayEnabled;

class VLookup extends LookupBase
{
    use ArrayEnabled;

    /**
     * VLOOKUP
     * The VLOOKUP function searches for value in the left-most column of lookup_array and returns the value
     *     in the same row based on the index_number.
     *
     * @param mixed $lookupValue The value that you want to match in lookup_array
     * @param mixed $lookupArray The range of cells being searched
     * @param mixed $indexNumber The column number in table_array from which the matching value must be returned.
     *                                The first column is 1.
     * @param mixed $notExactMatch determines if you are looking for an exact match based on lookup_value
     *
     * @return mixed The value of the found cell
     */
    public static function lookup($lookupValue, $lookupArray, $indexNumber, $notExactMatch = true)
    {
        if (is_array($lookupValue)) {
            return self::evaluateArrayArgumentsIgnore([self::class, __FUNCTION__], 1, $lookupValue, $lookupArray, $indexNumber, $notExactMatch);
        }

        if ($notExactMatch === null) {
            $rangeLookup = true;
        } else {
            $rangeLookup = (bool) $notExactMatch;
        }

        if (!is_array($lookupArray)) {
            return '#REF!';
        }

        if (!is_numeric($indexNumber)) {
            $excelErrorCodes = [
                'null' => '#NULL!',
                'divisionbyzero' => '#DIV/0!',
                'value' => '#VALUE!',
                'reference' => '#REF!',
                'name' => '#NAME?',
                'num' => '#NUM!',
                'na' => '#N/A',
                'gettingdata' => '#GETTING_DATA',
                'spill' => '#SPILL!',
                'connect' => '#CONNECT!',
                'blocked' => '#BLOCKED!',
                'unknown' => '#UNKNOWN!',
                'field' => '#FIELD!',
                'calculation' => '#CALC!',
            ];
            $indexError = '#VALUE!';
            foreach ($excelErrorCodes as $errorCode) {
                if ($indexNumber === $errorCode) {
                    $indexError = $errorCode;
                }
            }

            return $indexError;
        }

        if ($indexNumber < 1) {
            return '#VALUE!';
        }

        $rowIndexList = array_keys($lookupArray);
        if ($rowIndexList === []) {
            return '#REF!';
        }

        $validatedIndex = (int) $indexNumber;
        $probeRowKey = array_pop($rowIndexList);
        $probeRow = $lookupArray[$probeRowKey];
        if (!is_array($probeRow)) {
            return '#REF!';
        }
        $probeColumnCount = count($probeRow);
        if ($validatedIndex > $probeColumnCount) {
            return '#REF!';
        }

        $columnKeys = array_keys($probeRow);
        $returnColumnOffset = $validatedIndex - 1;
        $returnColumn = $columnKeys[$returnColumnOffset];
        $firstColumn = array_shift($columnKeys);
        if ($firstColumn === null) {
            $firstColumn = 1;
        }

        if ($rangeLookup === false) {
            $orderedKeys = array_keys($lookupArray);
            $orderedCount = count($orderedKeys);
            for ($leftPosition = 0; $leftPosition < $orderedCount; ++$leftPosition) {
                for ($rightPosition = $leftPosition + 1; $rightPosition < $orderedCount; ++$rightPosition) {
                    $leftKey = $orderedKeys[$leftPosition];
                    $rightKey = $orderedKeys[$rightPosition];
                    $leftRow = $lookupArray[$leftKey];
                    $rightRow = $lookupArray[$rightKey];
                    reset($leftRow);
                    reset($rightRow);
                    $leftFirstColumn = key($leftRow);
                    $rightFirstColumn = key($rightRow);
                    $leftText = (string) $leftRow[$leftFirstColumn];
                    $rightText = (string) $rightRow[$rightFirstColumn];
                    $leftLower = mb_convert_case($leftText, MB_CASE_LOWER, 'UTF-8');
                    $rightLower = mb_convert_case($rightText, MB_CASE_LOWER, 'UTF-8');
                    if ($leftLower > $rightLower) {
                        $orderedKeys[$leftPosition] = $rightKey;
                        $orderedKeys[$rightPosition] = $leftKey;
                    }
                }
            }
            $sortedLookup = [];
            foreach ($orderedKeys as $orderedKey) {
                $sortedLookup[$orderedKey] = $lookupArray[$orderedKey];
            }
            $lookupArray = $sortedLookup;
        }

        $lookupText = (string) $lookupValue;
        $lookupLower = mb_convert_case($lookupText, MB_CASE_LOWER, 'UTF-8');
        $matchedRow = null;
        foreach ($lookupArray as $rowKey => $rowData) {
            $cellValue = $rowData[$firstColumn];
            $cellText = (string) $cellValue;
            $cellDataLower = mb_convert_case($cellText, MB_CASE_LOWER, 'UTF-8');
            $lookupIsNumeric = is_numeric($lookupValue);
            $cellIsNumeric = is_numeric($cellValue);
            $bothNumeric = false;
            $bothNotNumeric = false;
            if ($lookupIsNumeric) {
                if ($cellIsNumeric) {
                    $bothNumeric = true;
                    if ($rangeLookup) {
                        if ($cellValue > $lookupValue) {
                            break;
                        }
                    }
                }
            } else {
                if ($cellIsNumeric) {
                    $bothNotNumeric = false;
                } else {
                    $bothNotNumeric = true;
                    if ($rangeLookup) {
                        if ($cellDataLower > $lookupLower) {
                            break;
                        }
                    }
                }
            }
            if ($bothNumeric) {
                if ($rangeLookup) {
                    $matchedRow = $rowKey;
                } elseif ($cellDataLower == $lookupLower) {
                    if ($matchedRow === null) {
                        $matchedRow = $rowKey;
                    } elseif ($rowKey < $matchedRow) {
                        $matchedRow = $rowKey;
                    }
                }
            } elseif ($bothNotNumeric) {
                if ($rangeLookup) {
                    $matchedRow = $rowKey;
                } elseif ($cellDataLower == $lookupLower) {
                    if ($matchedRow === null) {
                        $matchedRow = $rowKey;
                    } elseif ($rowKey < $matchedRow) {
                        $matchedRow = $rowKey;
                    }
                }
            }
        }

        if ($matchedRow !== null) {
            return $lookupArray[$matchedRow][$returnColumn];
        }

        return '#N/A';
    }
}

